-- Create "webhook_cursors" table
CREATE TABLE "webhook_cursors" ("id" character varying(40) NOT NULL, "endpoint_id" character varying(40) NOT NULL, "seq" bigint NOT NULL DEFAULT 0, "claimed_by" character varying(100) NULL, "claimed_until" timestamptz NULL, "attempts" bigint NOT NULL DEFAULT 0, "next_attempt_at" timestamptz NULL, "tenant_id" character varying(40) NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "webhook_cursors_tenants_webhook_cursors" FOREIGN KEY ("tenant_id") REFERENCES "tenants" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "webhook_cursors_attempts" CHECK ((attempts >= 0) AND (attempts <= 8)), CONSTRAINT "webhook_cursors_claim" CHECK ((claimed_by IS NULL) = (claimed_until IS NULL)), CONSTRAINT "webhook_cursors_id_format" CHECK ((id)::text ~ '^whc_[a-z2-7]{26}$'::text), CONSTRAINT "webhook_cursors_seq" CHECK (seq >= 0));
-- Create index "webhookcursor_endpoint_id" to table: "webhook_cursors"
CREATE UNIQUE INDEX "webhookcursor_endpoint_id" ON "webhook_cursors" ("endpoint_id");
-- Create index "webhookcursor_tenant_id_endpoint_id" to table: "webhook_cursors"
CREATE UNIQUE INDEX "webhookcursor_tenant_id_endpoint_id" ON "webhook_cursors" ("tenant_id", "endpoint_id");
-- Create "webhook_deliveries" table
CREATE TABLE "webhook_deliveries" ("id" character varying(40) NOT NULL, "endpoint_id" character varying(40) NOT NULL, "seq" bigint NOT NULL, "event_id" character varying(40) NOT NULL, "event_type" character varying(40) NOT NULL, "attempt" bigint NOT NULL, "outcome" character varying NOT NULL, "category" character varying(40) NOT NULL, "status_code" bigint NULL, "duration_ms" bigint NOT NULL, "attempted_at" timestamptz NOT NULL, "tenant_id" character varying(40) NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "webhook_deliveries_tenants_webhook_deliveries" FOREIGN KEY ("tenant_id") REFERENCES "tenants" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "webhook_deliveries_attempt" CHECK ((attempt >= 1) AND (attempt <= 8)), CONSTRAINT "webhook_deliveries_duration" CHECK (duration_ms >= 0), CONSTRAINT "webhook_deliveries_id_format" CHECK ((id)::text ~ '^whd_[a-z2-7]{26}$'::text), CONSTRAINT "webhook_deliveries_outcome" CHECK ((outcome)::text = ANY (ARRAY['success'::text, 'failure'::text])), CONSTRAINT "webhook_deliveries_status" CHECK ((status_code IS NULL) OR ((status_code >= 100) AND (status_code <= 599))));
-- Create index "webhookdelivery_attempted_at" to table: "webhook_deliveries"
CREATE INDEX "webhookdelivery_attempted_at" ON "webhook_deliveries" ("attempted_at");
-- Create index "webhookdelivery_tenant_id_endpoint_id_attempted_at" to table: "webhook_deliveries"
CREATE INDEX "webhookdelivery_tenant_id_endpoint_id_attempted_at" ON "webhook_deliveries" ("tenant_id", "endpoint_id", "attempted_at");
-- Create "webhook_endpoints" table
CREATE TABLE "webhook_endpoints" ("id" character varying(40) NOT NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "url_ciphertext" bytea NOT NULL, "url_display" character varying(300) NOT NULL, "events" jsonb NOT NULL, "secret_ciphertext" bytea NOT NULL, "previous_secret_ciphertext" bytea NULL, "previous_secret_until" timestamptz NULL, "enabled" boolean NOT NULL DEFAULT true, "disabled_reason" character varying(200) NULL, "tenant_id" character varying(40) NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "webhook_endpoints_tenants_webhook_endpoints" FOREIGN KEY ("tenant_id") REFERENCES "tenants" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "webhook_endpoints_disabled" CHECK (enabled OR (disabled_reason IS NOT NULL)), CONSTRAINT "webhook_endpoints_events" CHECK ((jsonb_typeof(events) = 'array'::text) AND (jsonb_array_length(events) > 0)), CONSTRAINT "webhook_endpoints_id_format" CHECK ((id)::text ~ '^whe_[a-z2-7]{26}$'::text), CONSTRAINT "webhook_endpoints_previous" CHECK ((previous_secret_ciphertext IS NULL) = (previous_secret_until IS NULL)));
-- Create index "webhookendpoint_tenant_id_id" to table: "webhook_endpoints"
CREATE UNIQUE INDEX "webhookendpoint_tenant_id_id" ON "webhook_endpoints" ("tenant_id", "id");
